package main

import (
	"encoding/json"
	"fmt"
	"os"
	"sort"
)

// The following struts were generated by a schema detector, run on a large
// alerts.json file.

type MainStruct struct {
	Alerts             []Alerts                          `json:"alerts"`
	Date               float64                           `json:"date"`
	LastPosted         float64                           `json:"last_posted"`
	LatestBuilderInfo  map[string]map[string]BuilderInfo `json:"latest_builder_info"`
	RangeGroups        []RangeGroups                     `json:"range_groups"`
	ReasonGroups       []ReasonGroups                    `json:"reason_groups"`
	StaleAlertsThresh  float64                           `json:"stale_alerts_thresh"`
	StaleBuilderAlerts []StaleBuilderAlerts              `json:"stale_builder_alerts"`
}

type RangeGroups struct {
	FailureKeys        []string  `json:"failure_keys"`
	MergedFirstFailing Revisions `json:"merged_first_failing"`
	MergedLastPassing  Revisions `json:"merged_last_passing"`
	SortKey            string    `json:"sort_key"`
}

type StaleBuilderAlerts struct {
	BuilderName    string  `json:"builder_name"`
	LastUpdateTime float64 `json:"last_update_time"`
	LatestBuild    float64 `json:"latest_build"`
	MasterUrl      string  `json:"master_url"`
	PendingBuilds  float64 `json:"pending_builds"`
	State          string  `json:"state"`
	Step           string  `json:"step"`
	Tree           string  `json:"tree"`
}

type Alerts struct {
	BuilderName      string    `json:"builder_name"`
	FailingBuild     float64   `json:"failing_build"`
	FailingRevisions Revisions `json:"failing_revisions"`
	Key              string    `json:"key"`
	LastFailingBuild float64   `json:"last_failing_build"`
	LastResultTime   float64   `json:"last_result_time"`
	LatestRevisions  Revisions `json:"latest_revisions"`
	MasterUrl        string    `json:"master_url"`
	PassingBuild     float64   `json:"passing_build"`
	PassingRevisions Revisions `json:"passing_revisions"`
	StepName         string    `json:"step_name"`
	Tree             string    `json:"tree"`
	WouldCloseTree   bool      `json:"would_close_tree"`
}

type Revisions struct {
	Blink    float64 `json:"blink"`
	Chromium float64 `json:"chromium"`
	V8       float64 `json:"v8"`
	Nacl     float64 `json:"nacl"`
}

type ReasonGroups struct {
	FailureKeys        []string  `json:"failure_keys"`
	LikelyRevisions    []string  `json:"likely_revisions"`
	MergedFirstFailing Revisions `json:"merged_first_failing"`
	MergedLastPassing  Revisions `json:"merged_last_passing"`
	SortKey            string    `json:"sort_key"`
}

type BuilderInfo struct {
	BuildSource    string    `json:"build_source"`
	LastUpdateTime float64   `json:"lastUpdateTime"`
	MonitorUrl     string    `json:"monitor_url"`
	Revisions      Revisions `json:"revisions"`
	State          string    `json:"state"`
}

type counter struct {
	key string
	c   int64
}
type counters []counter

func topN(m map[string]int64) []string {
	c := make([]counter, 0)
	for k, v := range m {
		c = append(c, counter{k, v})
	}

	sort.Sort(counters(c))

	ret := make([]string, 0)
	for i := 0; i < 10 && i < len(c); i++ {
		ret = append(ret, c[i].key)
	}
	return ret
}

func (a counters) Len() int           { return len(a) }
func (a counters) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a counters) Less(i, j int) bool { return a[i].c > a[j].c }

func analyze(m MainStruct) {
	fmt.Printf("%d alerts\n%d range_groups\n%d reason_groups\n%d stale_builder_alerts\n",
		len(m.Alerts), len(m.RangeGroups), len(m.ReasonGroups), len(m.StaleBuilderAlerts))

	builders := make(map[string]int64)
	masters := make(map[string]int64)
	trees := make(map[string]int64)
	for _, a := range m.Alerts {
		builders[a.BuilderName]++
		masters[a.MasterUrl]++
		trees[a.Tree]++
	}

	fmt.Print("Builders:\n")
	for _, k := range topN(builders) {
		fmt.Printf("%s: %d\n", k, builders[k])
	}

	fmt.Print("Masters:\n")
	for _, k := range topN(masters) {
		fmt.Printf("%s: %d\n", k, masters[k])
	}

	fmt.Print("Trees:\n")
	for _, k := range topN(trees) {
		fmt.Printf("%s: %d\n", k, trees[k])
	}
}

func main() {
	dec := json.NewDecoder(os.Stdin)
	var f MainStruct
	if err := dec.Decode(&f); err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	analyze(f)
}
